      "player_spawn": {"x": -3009.5, "y": 71.0, "z": -5572.5},
      "stone_platform": {"x_min": -3018, "x_max": -3002, "y": 70, "z_min": -5581, "z_max": -5565},
      "purple_wool_cluster": {"x_min": -3006, "x_max": -3005, "y_min": 71, "y_max": 73, "z_min": -5570, "z_max": -5569},
      "milestone_2_box": {"x_min": -3014, "x_max": -3008, "y_min": 71, "y_max": 75, "z_min": -5577, "z_max": -5571},
      "overlap_check": "NO OVERLAP between wool cluster and milestone box — ✅"
    }
  },
  "overall_status": "NEEDS_MINOR_REVISION",
